import{i as e}from"./preload-helper-CT_b8DTk.js";import{t}from"./iframe-BJZP98JJ.js";import{d as n,f as r,j as i,y as a}from"./blocks-28IqVyiG.js";import{t as o}from"./mdx-react-shim-MhT3IHHe.js";var s,c=e((()=>{s="# jb-time-picker-react\n\nReact component wrapper around [`jb-time-picker`](https://github.com/javadbat/jb-time-picker). The wrapper forwards the web component API while providing typed props and event callbacks.\n\n## Installation\n\n```bash\nnpm i jb-time-picker-react\n```\n\n## Usage\n\n```tsx\nimport { JBTimePicker } from 'jb-time-picker-react';\n\nexport function TimePickerSample() {\n  return (\n    <JBTimePicker\n      value={{ hour: 3, minute: 10, second: 20 }}\n      leadingZero\n      onChange={(e) => console.log(e.target.value)}\n    />\n  );\n}\n```\n\nSee the [default React demo](https://javadbat.github.io/design-system/?path=/story/components-jbtimepicker--normal) for the interactive picker.\n\nYou can also pass the value as a time string:\n\n```tsx\n<JBTimePicker value=\"03:10:20\" />\n```\n\n## Props\n\n| prop | type | description |\n| --- | --- | --- |\n| `value` | `{ hour: number, minute: number, second?: number } \\| string \\| null` | Controlled object or `HH:mm[:ss]` value. [Demo](https://javadbat.github.io/design-system/?path=/story/components-jbtimepicker--with-value) |\n| `secondEnabled` | `boolean` | Shows or hides the second unit. [Demo](https://javadbat.github.io/design-system/?path=/story/components-jbtimepicker--without-second) |\n| `leadingZero` | `boolean` | Displays values below 10 with a leading zero. [Demo](https://javadbat.github.io/design-system/?path=/story/components-jbtimepicker--leading-zero) |\n| `optionalUnits` | `('hour' \\| 'minute' \\| 'second')[]` | Marks selected units as optional/muted. [Demo](https://javadbat.github.io/design-system/?path=/story/components-jbtimepicker--optional-minute) |\n| `showPersianNumber` | `boolean` | Displays Persian digits while the value remains numeric. [Demo](https://javadbat.github.io/design-system/?path=/story/components-jbtimepicker--persian-number) |\n| `textWidth` | `number \\| null` | Sets SVG `textLength` for custom-font alignment. [Demo](https://javadbat.github.io/design-system/?path=/story/components-jbtimepicker--text-width) |\n| `onLoad` | `(event) => void` | Runs before initialization. [Demo](https://javadbat.github.io/design-system/?path=/story/components-jbtimepicker--event-test) |\n| `onInit` | `(event) => void` | Runs after initialization. [Demo](https://javadbat.github.io/design-system/?path=/story/components-jbtimepicker--event-test) |\n| `onChange` | `(event) => void` | Runs when the user changes a time unit. [Demo](https://javadbat.github.io/design-system/?path=/story/components-jbtimepicker--event-test) |\n\n## Demo\n\n- [Demo](https://javadbat.github.io/design-system/?path=/story/components-jbtimepicker--normal) for the default picker.\n- [Demo](https://javadbat.github.io/design-system/?path=/story/components-jbtimepicker--without-second) for hour/minute-only mode.\n- [Demo](https://javadbat.github.io/design-system/?path=/story/components-jbtimepicker-style--gallery) for style recipes.\n\n## When to use\n\nUse `JBTimePicker` when a React view needs an inline time picker for hour, minute, and optionally second selection. [Demo](https://javadbat.github.io/design-system/?path=/story/components-jbtimepicker--normal)\n\nUse `JBTimeInput` when the user should type into a form field and open a picker from that input.\n\n## Value\n\n`value` accepts either an object with `hour`, `minute`, and optional `second`, or a time string such as `\"03:10:20\"`. Read `event.target.value` from `onChange`; see the [controlled value demo](https://javadbat.github.io/design-system/?path=/story/components-jbtimepicker--with-value) and [value interaction demo](https://javadbat.github.io/design-system/?path=/story/components-jbtimepicker--value-test).\n\n## Focus a time unit\n\nUse a ref for imperative web-component methods such as focusing a specific time unit when the picker should guide the next edit. [Demo](https://javadbat.github.io/design-system/?path=/story/components-jbtimepicker--focused-unit)\n\n## Disable seconds\n\nSet `secondEnabled={false}` for hour/minute-only picking. [Demo](https://javadbat.github.io/design-system/?path=/story/components-jbtimepicker--without-second)\n\n```tsx\n<JBTimePicker secondEnabled={false} value=\"03:10\" />\n```\n\n## Display options\n\nUse `leadingZero`, `optionalUnits`, `showPersianNumber`, and `textWidth` to match the web-component display behavior from React. See the [leading-zero](https://javadbat.github.io/design-system/?path=/story/components-jbtimepicker--leading-zero), [optional-unit](https://javadbat.github.io/design-system/?path=/story/components-jbtimepicker--optional-minute), [Persian-number](https://javadbat.github.io/design-system/?path=/story/components-jbtimepicker--persian-number), and [text-width](https://javadbat.github.io/design-system/?path=/story/components-jbtimepicker--text-width) demos.\n\n## RTL layouts\n\nPlace `JBTimePicker` in an RTL container when it is part of a right-to-left interface. [Demo](https://javadbat.github.io/design-system/?path=/story/components-jbtimepicker--rtl-sample)\n\n## Events\n\nUse `onLoad` and `onInit` for lifecycle notifications and `onChange` for user edits. [Demo](https://javadbat.github.io/design-system/?path=/story/components-jbtimepicker--event-test)\n\n## CSS parts and variables\n\nThe React wrapper uses the same CSS parts and variables as the web component. See the [web-component styling guide](../README.md#css-parts-and-variables) and [style gallery](https://javadbat.github.io/design-system/?path=/story/components-jbtimepicker-style--gallery).\n\n```css\n.compact-time-picker {\n  --jb-time-picker-minute-color: #2563eb;\n}\n```\n\n## Accessibility notes\n\nProvide nearby label text that describes the time being selected; review the [interactive accessibility example](https://javadbat.github.io/design-system/?path=/story/components-jbtimepicker--normal). Prefer `JBTimeInput` when the time value is part of a larger form and needs a conventional labeled input.\n\n## Shared Documentation\n\nFor web-component behavior, events, and CSS variables, see [`jb-time-picker`](https://github.com/javadbat/jb-time-picker).\n"}));function l(e){return(0,d.jsxs)(d.Fragment,{children:[(0,d.jsx)(r,{title:`Components/JBTimePicker/React Readme`}),`
`,(0,d.jsx)(n,{children:s})]})}function u(e={}){let{wrapper:t}={...i(),...e.components};return t?(0,d.jsx)(t,{...e,children:(0,d.jsx)(l,{...e})}):l(e)}var d;e((()=>{d=t(),o(),a(),c()}))();export{u as default};